{
  "title": "Scholarship Applications Report",
  "subtitle": "Summary of scholarship applications for our board",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Total applications", "sql": "SELECT COUNT(*) AS n FROM scholarship_applicants", "unit": ""},
