    {"id": "p3", "kind": "line", "title": "Applications by district", "sql": "SELECT District, COUNT(*) AS n FROM scholarship_applicants GROUP BY 1 ORDER BY 2 DESC", "x": "District", "y": ["n"]},
    {"id": "p4", "kind": "table", "title": "Top 10 districts by applications", "sql": "SELECT District, COUNT(*) AS n FROM scholarship_applicants GROUP BY 1 ORDER BY 2 DESC LIMIT 10"}
  ],
  "narrative": "The total number of applications is {{p1}}. The majority of applications come from the General category, with {{p2.n}} applications. The districts with the most applications are {{p3.n}}. The top 10 districts by applications are listed below. We recommend reviewing the applications from these districts first."
}

