    {"id": "p5", "kind": "pie", "title": "Pending cases by scheme", "sql": "SELECT Name of scheme, COUNT(*) AS n FROM scholarship_applicants WHERE Status = 'Pending' GROUP BY 1 ORDER BY 2 DESC LIMIT 5", "x": "Name of scheme", "y": ["n"]}
  ],
  "narrative": "The number of pending cases is {{p1}}. The districts with the most pending cases are {{p2}}. The top 5 districts with pending cases are {{p3.n}}. The number of pending cases has been increasing over time, with {{p4.n}} cases in the latest year. The majority of pending cases are for the {{p5}} scheme."
}

