{
  "title": "Kids' improvement dashboard",
  "subtitle": "How kids improved from baseline to endline, by location and coach",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Total children", "sql": "SELECT COUNT(*) AS n FROM baseline UNION ALL SELECT COUNT(*) AS n FROM endline", "unit": ""},
    {"id": "p2", "kind": "bar", "title": "Children by location", "sql": "SELECT Location AS x, COUNT(*) AS y FROM (SELECT Location FROM baseline UNION ALL SELECT Location FROM endline) GROUP BY 1 ORDER BY 2 DESC", "x": "Location", "y": ["y"]},
    {"id": "p3", "kind": "bar", "title": "Children by coach", "sql": "SELECT Coach AS x, COUNT(*) AS y FROM (SELECT Coach FROM baseline UNION ALL SELECT Coach FROM endline) GROUP BY 1 ORDER BY 2 DESC", "x": "Coach", "y": ["y"]},
    {"id": "p4", "kind": "table", "title": "Top 10 locations by children", "sql": "SELECT Location AS x, COUNT(*) AS y FROM (SELECT Location FROM baseline UNION ALL SELECT Location FROM endline) GROUP BY 1 ORDER BY 2 DESC LIMIT 10", "x": "x", "y": ["y"]},
    {"id": "p5", "kind": "table", "title": "Top 10 coaches by children", "sql": "SELECT Coach AS x, COUNT(*) AS y FROM (SELECT Coach FROM baseline UNION ALL SELECT Coach FROM endline) GROUP BY 1 ORDER BY 2 DESC LIMIT 10", "x": "x", "y": ["y"]},
    {"id": "p6", "kind": "line", "title": "Children by month", "sql": "SELECT month, COUNT(*) AS y FROM (SELECT EXTRACT(MONTH FROM DOB) AS month FROM baseline UNION ALL SELECT EXTRACT(MONTH FROM DOB) AS month FROM endline) GROUP BY 1 ORDER BY 1", "x": "month", "y": ["y"]}
  ],
  "narrative": "The number of children improved from {{p1}} to {{p1.n}}. The top 10 locations by children are {{p4.x}}. The top 10 coaches by children are {{p5.x}}. The number of children by month is {{p6.y}}."
}

{
  "title": "Child Progress",
  "subtitle": "How children improved from baseline to endline, by location and coach",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Total children", "sql": "SELECT COUNT(*) AS n FROM (SELECT DISTINCT \"Child ID\" FROM baseline UNION ALL SELECT DISTINCT \"Child ID\" FROM endline) AS combined", "unit": ""},
    {"id": "p2", "kind": "bar", "title": "Average improvement by location", "sql": "SELECT \"Location\" AS location, AVG(NULLIF(\"Shuttle run sec\" - e.\"Shuttle run sec\", 0)) AS avg_improvement FROM baseline b JOIN endline e ON b.\"Child ID\" = e.\"Child ID\" GROUP BY 1 ORDER BY 2 DESC LIMIT 10", "x": "location", "y": ["avg_improvement"]},
    {"id": "p3", "kind": "bar", "title": "Average improvement by coach", "sql": "SELECT \"Coach\" AS coach, AVG(NULLIF(\"Shuttle run sec\" - e.\"Shuttle run sec\", 0)) AS avg_improvement FROM baseline b JOIN endline e ON b.\"Child ID\" = e.\"Child ID\" GROUP BY 1 ORDER BY 2 DESC LIMIT 10", "x": "coach", "y": ["avg_improvement"]},
    {"id": "p4", "kind": "table", "title": "Top 10 locations by improvement", "sql": "SELECT \"Location\", AVG(NULLIF(\"Shuttle run sec\" - e.\"Shuttle run sec\", 0)) AS avg_improvement FROM baseline b JOIN endline e ON b.\"Child ID\" = e.\"Child ID\" GROUP BY 1 ORDER BY 2 DESC LIMIT 10"}
  ],
  "narrative": "The children showed significant improvement in shuttle run time, with the top 10 locations and coaches leading the way. The average improvement was {{p2}} seconds in {{p3}}. The total number of children involved in the program was {{p1}}."
}

{
  "title": "Improvement by Gender",
  "subtitle": "Compare improvement of girls and boys over time",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Girls improving", "sql": "SELECT COUNT(*) AS n FROM (SELECT * FROM baseline WHERE Gender = 'Female') INTERSECT SELECT * FROM endline WHERE Gender = 'Female')", "unit": ""},
    {"id": "p2", "kind": "kpi", "title": "Boys improving", "sql": "SELECT COUNT(*) AS n FROM (SELECT * FROM baseline WHERE Gender = 'Male') INTERSECT SELECT * FROM endline WHERE Gender = 'Male')", "unit": ""},
    {"id": "p3", "kind": "bar", "title": "Average improvement by gender", "sql": "SELECT Gender, AVG(CASE WHEN baseline.\"Shuttle run sec\" IS NULL THEN NULL ELSE (endline.\"Shuttle run sec\" - baseline.\"Shuttle run sec\") END) AS avg_improvement FROM baseline INNER JOIN endline ON baseline.\"Child ID\" = endline.\"Child ID\" GROUP BY 1 ORDER BY 2 DESC", "x": "Gender", "y": ["avg_improvement"]},
    {"id": "p4", "kind": "table", "title": "Girls and boys by location", "sql": "SELECT Gender, Location, COUNT(*) AS n FROM baseline INTERSECT SELECT Gender, Location, COUNT(*) AS n FROM endline GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 10"}
  ],
  "narrative": "Girls are improving at a rate of {{p3}} compared to {{p2}}. The top 10 locations with the most improvement are {{p4.n}} girls and {{p4.n}} boys."
}

{
  "title": "Improvement by Gender",
  "subtitle": "Are girls and boys improving equally?",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Girls improving", "sql": "SELECT COUNT(*) AS n FROM (SELECT * FROM baseline WHERE Gender = 'Female') INTERSECT SELECT * FROM endline WHERE Gender = 'Female'", "unit": ""},
    {"id": "p2", "kind": "kpi", "title": "Boys improving", "sql": "SELECT COUNT(*) AS n FROM (SELECT * FROM baseline WHERE Gender = 'Male') INTERSECT SELECT * FROM endline WHERE Gender = 'Male'", "unit": ""},
    {"id": "p3", "kind": "bar", "title": "Average shuttle run by gender", "sql": "SELECT Gender, AVG(CASE WHEN baseline.\"Shuttle run sec\" IS NULL THEN NULL ELSE baseline.\"Shuttle run sec\" END) AS avg_shuttle FROM baseline INTERSECT SELECT Gender, AVG(CASE WHEN endline.\"Shuttle run sec\" IS NULL THEN NULL ELSE endline.\"Shuttle run sec\" END) AS avg_shuttle FROM endline GROUP BY 1 ORDER BY 2 DESC", "x": "Gender", "y": ["avg_shuttle"]},
    {"id": "p4", "kind": "table", "title": "Girls and boys by location", "sql": "SELECT Gender, Location, COUNT(*) AS n FROM baseline INTERSECT SELECT Gender, Location, COUNT(*) AS n FROM endline GROUP BY 1, 2"}
  ],
  "narrative": "Girls {{p1.n}} and boys {{p2.n}}. The average shuttle run for girls is {{p3.avg_shuttle}} and for boys is {{p3.avg_shuttle}}. The number of girls and boys by location is {{p4.n}}."
}

{
  "title": "Donation Dashboard",
