    {"id": "p5", "kind": "bar", "title": "Payment modes", "sql": "SELECT Mode, COUNT(*) AS count FROM donor_transactions GROUP BY 1 ORDER BY 2 DESC LIMIT 10", "x": "Mode", "y": ["count"]},
    {"id": "p6", "kind": "table", "title": "Repeat donors", "sql": "SELECT Donor, COUNT(*) AS count FROM donor_transactions GROUP BY 1 HAVING COUNT(*) > 1"}
  ],
  "narrative": "Donations have been made in {{p1}} different ways, with a total amount of {{p2}}. The average donation is {{p3}}. The top cities for donations are {{p4}}, and the most common payment modes are {{p5}}. We have {{p6.count}} repeat donors."
