{
  "title": "School Dashboard",
  "subtitle": "Enrolment trend, infrastructure gaps, and girls vs boys",
  "panels": [
    {"id": "p1", "kind": "kpi", "title": "Total schools", "sql": "SELECT COUNT(*) AS n FROM school_enrolment_by_year", "unit": ""},
    {"id": "p2", "kind": "bar", "title": "Girls vs Boys Enrolment", "sql": "SELECT year, SUM(Girls 2022) AS girls_2022, SUM(Boys 2022) AS boys_2022 FROM school_enrolment_by_year GROUP BY 1 ORDER BY 1", "x": "year", "y": ["girls_2022", "boys_2022"]},
    {"id": "p3", "kind": "bar", "title": "Girls vs Boys Enrolment Trend", "sql": "SELECT year, SUM(Girls 2023) AS girls_2023, SUM(Boys 2023) AS boys_2023 FROM school_enrolment_by_year GROUP BY 1 ORDER BY 1", "x": "year", "y": ["girls_2023", "boys_2023"]},
    {"id": "p4", "kind": "bar", "title": "Girls vs Boys Enrolment Trend", "sql": "SELECT year, SUM(Girls 2024) AS girls_2024, SUM(Boys 2024) AS boys_2024 FROM school_enrolment_by_year GROUP BY 1 ORDER BY 1", "x": "year", "y": ["girls_2024", "boys_2024"]},
    {"id": "p5", "kind": "bar", "title": "Infrastructure Gaps", "sql": "SELECT 'Toilets functional (girls)' AS category, COUNT(CASE WHEN Toilets functional (girls) = 'Yes' THEN 1 ELSE NULL END) AS toilets, COUNT(CASE WHEN Drinking water = 'Yes' THEN 1 ELSE NULL END) AS drinking_water, COUNT(CASE WHEN Electricity = 'Yes' THEN 1 ELSE NULL END) AS electricity FROM school_infrastructure", "x": "category", "y": ["toilets", "drinking_water", "electricity"]},
    {"id": "p6", "kind": "table", "title": "School Infrastructure", "sql": "SELECT School Code, Toilets functional (girls), Drinking water, Electricity, Inspected On FROM school_infrastructure"}
  ],
  "narrative": "The school dashboard provides an overview of enrolment trends over the years, infrastructure gaps, and girls vs boys enrolment. The total number of schools is {{p1}}. The enrolment trend shows a steady increase in girls vs boys enrolment over the years. The infrastructure gaps highlight the need for improvement in toilets, drinking water, and electricity facilities. The school infrastructure table provides a detailed view of the infrastructure status of each school."
}

